            let either = file_transactions.get(a).copied().unwrap_or(0)
                + file_transactions.get(b).copied().unwrap_or(0)
                - support;
            CoupledFiles {
                a: a.to_string(),
                b: b.to_string(),
                support: *support,
                either,
                confidence: *support as f64 / either as f64,
            }
        })
        .collect

